<?php
namespace App\Http\Controllers; use App\Models\SeniorCitizen; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class SeniorCitizenController extends Controller {
 public function index(Request $r){$q=SeniorCitizen::query();if($s=$r->get('search'))$q->where(fn($w)=>$w->where('first_name','like',"%$s%")->orWhere('last_name','like',"%$s%")->orWhere('osca_id','like',"%$s%"));if($b=$r->get('barangay'))$q->where('barangay',$b);if($st=$r->get('status'))$q->where('status',$st);return view('seniors.index',['seniors'=>$q->orderBy('last_name')->paginate(10)->withQueryString(),'barangays'=>SeniorCitizen::whereNotNull('barangay')->distinct()->orderBy('barangay')->pluck('barangay')]);}
 public function create(){return view('seniors.form',['senior'=>new SeniorCitizen]);} public function store(Request $r){SeniorCitizen::create($this->data($r));return redirect()->route('seniors.index')->with('success','Senior citizen record added.');} public function show(SeniorCitizen $senior){$senior->load(['assistanceRequests'=>fn($q)=>$q->latest(),'benefits'=>fn($q)=>$q->latest()]);return view('seniors.show',compact('senior'));} public function edit(SeniorCitizen $senior){return view('seniors.form',compact('senior'));} public function update(Request $r,SeniorCitizen $senior){$senior->update($this->data($r,$senior));return redirect()->route('seniors.show',$senior)->with('success','Record updated.');} public function destroy(SeniorCitizen $senior){if($senior->assistanceRequests()->exists()||$senior->benefits()->exists())return back()->with('error','This record has linked requests or benefits. Change its status to Inactive instead.');$senior->delete();return redirect()->route('seniors.index')->with('success','Record deleted.');}
 private function data(Request $r,?SeniorCitizen $s=null){return $r->validate(['osca_id'=>['nullable','string','max:50',Rule::unique('senior_citizens','osca_id')->ignore($s?->id)],'first_name'=>'required|string|max:100','middle_name'=>'nullable|string|max:100','last_name'=>'required|string|max:100','suffix'=>'nullable|string|max:20','birth_date'=>'required|date|before_or_equal:today','sex'=>'required|in:Female,Male,Prefer not to say','civil_status'=>'nullable|in:Single,Married,Widowed,Separated,Other','phone'=>'nullable|string|max:30','address'=>'required|string|max:255','barangay'=>'required|string|max:120','registration_date'=>'required|date','status'=>'required|in:Active,Inactive,Deceased','notes'=>'nullable|string|max:2000']);}
}
